"""Customer, loyalty ledger, and coupon models (P5)."""

from datetime import datetime
from typing import Optional

from pydantic import BaseModel, Field


class Customer(BaseModel):
    """Store-scoped profile keyed by phone. Never share across stores."""
    id: str = Field(default_factory=lambda: __import__("uuid").uuid4().hex)
    store_id: str
    name: str
    phone: str
    # membership tier: only members earn & redeem points; the member number is a
    # short human-typable code (generated by the owner or auto-assigned on upgrade)
    is_member: bool = False
    member_no: Optional[str] = None
    points: int = 0
    lifetime_spend: int = 0
    order_count: int = 0
    last_order_at: Optional[datetime] = None
    marketing_opt_in: bool = False   # P5.4: consent required before promotional contact
    created_at: datetime = Field(default_factory=lambda: datetime.now(__import__("datetime").timezone.utc))
    updated_at: datetime = Field(default_factory=lambda: datetime.now(__import__("datetime").timezone.utc))


class LedgerEntry(BaseModel):
    """Auditable points movement. Idempotency: (order_id, reason) is unique for the
    automatic reasons, so retries and double-hooks can never award twice."""
    id: str = Field(default_factory=lambda: __import__("uuid").uuid4().hex)
    customer_id: str
    store_id: str
    order_id: Optional[str] = None
    delta: int                                  # +earn, -redeem, -reversal, +/-adjust
    reason: str                                 # order_paid | redeem | reversal_void | reversal_refund | adjust
    actor: Optional[str] = None                 # staff name for manual adjustments
    note: Optional[str] = None
    created_at: datetime = Field(default_factory=lambda: datetime.now(__import__("datetime").timezone.utc))


class CustomerDetail(BaseModel):
    customer: Customer
    ledger: list[LedgerEntry] = []
    recent_orders: list[dict] = []


class PointsAdjustIn(BaseModel):
    delta: int = Field(ge=-100000, le=100000)
    reason: str = Field(min_length=3, max_length=200)


class CustomerUpdateIn(BaseModel):
    name: Optional[str] = Field(default=None, max_length=60)
    phone: Optional[str] = Field(default=None, min_length=9, max_length=16, pattern=r"^\+?\d+$")
    marketing_opt_in: Optional[bool] = None
    is_member: Optional[bool] = None
    # empty/None while is_member=True lets the server generate one automatically
    member_no: Optional[str] = Field(default=None, min_length=4, max_length=16, pattern=r"^[A-Za-z0-9-]+$")


class LoyaltyConfigIn(BaseModel):
    """Owner-editable loyalty rules (per store). Same semantics as lib/loyalty.py."""
    points_per: int = Field(default=1000, ge=1, le=1000000)
    min_spend_to_earn: int = Field(default=5000, ge=0)
    redeem_value_per_point: int = Field(default=10, ge=1, le=10000)
    redeem_min_points: int = Field(default=100, ge=1)
    redeem_max_fraction: float = Field(default=0.5, gt=0, le=1)


class Coupon(BaseModel):
    id: str = Field(default_factory=lambda: __import__("uuid").uuid4().hex)
    store_id: str
    code: str                                   # normalized uppercase
    description: str = ""
    type: str                                   # "fixed" | "percent"
    value: int                                  # IDR for fixed; percent 1-100 for percent
    min_spend: int = 0
    starts_at: Optional[datetime] = None
    ends_at: Optional[datetime] = None
    max_redemptions: int = 0                    # 0 = unlimited
    per_customer_limit: int = 0                 # 0 = unlimited
    used_count: int = 0                         # atomic; never decremented below truth
    applies_to: dict = Field(default_factory=lambda: {"type": "all"})
    active: bool = True
    created_at: datetime = Field(default_factory=lambda: datetime.now(__import__("datetime").timezone.utc))


class CouponIn(BaseModel):
    code: str = Field(min_length=3, max_length=32, pattern=r"^[A-Za-z0-9_-]+$")
    description: str = Field(default="", max_length=200)
    type: str = Field(pattern="^(fixed|percent)$")
    value: int = Field(gt=0)
    min_spend: int = Field(default=0, ge=0)
    starts_at: Optional[datetime] = None
    ends_at: Optional[datetime] = None
    max_redemptions: int = Field(default=0, ge=0)
    per_customer_limit: int = Field(default=0, ge=0)
    applies_to: dict = Field(default_factory=lambda: {"type": "all"})
    active: bool = True


class CouponUpdateIn(BaseModel):
    """Owner edits. `code` stays immutable (orders snapshot it by code); value/type may
    change — already-taken orders keep their snapshot, so history is never rewritten."""
    description: Optional[str] = Field(default=None, max_length=200)
    type: Optional[str] = Field(default=None, pattern="^(fixed|percent)$")
    value: Optional[int] = Field(default=None, gt=0)
    min_spend: Optional[int] = Field(default=None, ge=0)
    starts_at: Optional[datetime] = None
    ends_at: Optional[datetime] = None
    max_redemptions: Optional[int] = Field(default=None, ge=0)
    per_customer_limit: Optional[int] = Field(default=None, ge=0)
    applies_to: Optional[dict] = None
    active: Optional[bool] = None
